import {
  petHatchSoundCue,
  petSoundCue,
  petVoiceClip,
  type PetHatchedStage,
  type PetReaction,
  type PetSpecies,
} from "@zoption/shared";

import { soundEffectsPreference } from "./browserPreferences";

// The per-stage pet voices in public/pet/sounds, generated by scripts/generate-pet-sounds.mjs.

const players = new Map<string, HTMLAudioElement>();
const playGeneration = new Map<string, number>();
let delayedClipTimer: ReturnType<typeof setTimeout> | null = null;

function playerFor(name: string): HTMLAudioElement {
  let player = players.get(name);
  if (!player) {
    player = new Audio(`/pet/sounds/${name}.wav`);
    player.preload = "auto";
    // Let the playback rate move the pitch for combo lift and fading droop.
    player.preservesPitch = false;
    players.set(name, player);
  }
  return player;
}

function clearDelayedClip(): void {
  if (delayedClipTimer !== null) {
    clearTimeout(delayedClipTimer);
    delayedClipTimer = null;
  }
}

function playClip(name: string, rate: number, volume: number): void {
  const player = playerFor(name);
  playGeneration.set(name, (playGeneration.get(name) ?? 0) + 1);
  player.muted = false;
  player.playbackRate = rate;
  player.volume = volume;
  // Restart, so a quick second click is heard rather than ignored.
  player.currentTime = 0;
  player.play().catch(() => {
    // Sound is decoration; a blocked or missing clip stays silent.
  });
}

function scheduleClip(name: string, delayMs: number, rate: number, volume: number): void {
  clearDelayedClip();
  delayedClipTimer = setTimeout(() => {
    delayedClipTimer = null;
    if (!soundEffectsPreference.get() || typeof Audio === "undefined") return;
    playClip(name, rate, volume);
  }, delayMs);
}

/**
 * Unlocks an HTMLAudioElement inside a synchronous click gesture so browsers like Safari still
 * permit playback after an async network request (such as POST /api/app/pet/hatch).
 */
function unlockPlayer(name: string): void {
  const player = playerFor(name);
  const generation = playGeneration.get(name) ?? 0;
  player.muted = true;
  void Promise.resolve(player.play())
    .then(() => {
      if ((playGeneration.get(name) ?? 0) !== generation) return;
      player.pause();
      player.currentTime = 0;
      player.muted = false;
    })
    .catch(() => {
      if ((playGeneration.get(name) ?? 0) === generation) player.muted = false;
    });
}

/** Starts loading one pet's current-stage voices and the sparkle ahead of the first click. */
export function warmUpPetVoices(species: PetSpecies, stage: PetHatchedStage): void {
  if (!soundEffectsPreference.get() || typeof Audio === "undefined") return;
  for (const name of [
    petVoiceClip(species, stage, "happy"),
    petVoiceClip(species, stage, "sad"),
    "sparkle",
  ]) {
    playerFor(name);
  }
}

/** Call synchronously on the final hatch click so Safari keeps audio unlocked across the API call. */
export function unlockPetHatchAudio(species: PetSpecies): void {
  if (!soundEffectsPreference.get() || typeof Audio === "undefined") return;
  const cue = petHatchSoundCue(species);
  unlockPlayer("sparkle");
  unlockPlayer(cue.voiceClip);
}

/**
 * Plays the pet's stage-specific voice for a reaction, plus a staggered sparkle on a dance. Only
 * while this browser's Sound effects switch is on. Fire and forget.
 */
export function playPetReaction(
  species: PetSpecies,
  stage: PetHatchedStage,
  reaction: PetReaction,
): void {
  clearDelayedClip();
  if (!soundEffectsPreference.get() || typeof Audio === "undefined") return;
  const cue = petSoundCue(species, stage, reaction);
  playClip(cue.clip, cue.rate, cue.volume);
  if (cue.sparkle) {
    scheduleClip("sparkle", cue.sparkle.delayMs, 1, cue.sparkle.volume);
  }
}

/** Celebrates an egg hatching with the sparkle jingle followed by the newly hatched Baby's voice. */
export function playPetHatch(species: PetSpecies): void {
  clearDelayedClip();
  if (!soundEffectsPreference.get() || typeof Audio === "undefined") return;
  const cue = petHatchSoundCue(species);
  playClip("sparkle", 1, cue.sparkleVolume);
  scheduleClip(cue.voiceClip, cue.voiceDelayMs, 1, cue.voiceVolume);
}
